export declare const SERVER = "Vestige";
export declare const SUBTITLE = "Keeper of Vestige";
/** The archive is the metaphor for storage: things are kept there, not "saved". */
export declare const ARCHIVE = "the Vestige archive";
/** Same phrase, for the start of a sentence. */
export declare const ARCHIVE_CAP = "The Vestige archive";
/** The line a player gets when a dinosaur goes in. */
export declare const SECURED = "Your dinosaur has been secured in the Vestige archive.";
/** Shown under the panels, so the bot signs its own work. */
export declare const SIGNATURE = "Vesta \u00B7 Keeper of Vestige";
